def extend(add,CAT):
 id='impl-001_lever__departmental_hiring_trends'
 add(id,'department_strength_referral',"'Standard Operations' AS department_strength","CASE WHEN referral_rate>=30 THEN 'Strong Referral Network' ELSE 'Standard Operations' END AS department_strength",'只恢复契约规定的首个referral>=30分支；文字未写死，用诊断所得gold表达测量该分支贡献，不把这个英文标签当契约要求。')
 id='impl-001_lever__hiring_manager_scorecard'
 add(id,'development_recommendations',"'' development_recommendations","concat(CASE WHEN requisition_fill_rate<50 THEN 'Focus on requirement clarity; ' ELSE '' END,CASE WHEN coalesce(p.avg_applications_per_posting,0)<10 THEN 'Improve job posting appeal; ' ELSE '' END,CASE WHEN interview_success_rate<80 THEN 'Improve interview coordination; ' ELSE '' END,CASE WHEN avg_total_days_to_hire>60 THEN 'Accelerate decision process; ' ELSE '' END) development_recommendations",'恢复四段条件拼接，沿原SQL的现有指标值；缺失其他指标仍保留原值。仅文字代表采用gold已有片段/语义表述，不把gold当规则。')
 id='impl-002_int_pendo__product_health_metrics'
 add(id,'primary_improvement_area',"'Improve feature adoption' primary_improvement_area","CASE WHEN coalesce(net_promoter_score,-1)<0 THEN 'Focus on customer satisfaction and NPS improvement' ELSE 'Improve feature adoption' END primary_improvement_area",'只恢复契约首优先NPS缺失视为-1分支；条件源于契约，文字代表由只读gold诊断获得。')
 id='impl-002_int_pendo__data_quality_checks'
 # Omitted details are one report-section point; each section can be inserted at one location independently.
 old=CAT[id]['sql'];end='current_timestamp calculated_at'
 details=[('completeness_account',"SELECT 'Data Completeness Details','account_history',count(*)::FLOAT,count(*) FILTER(WHERE account_id IS NULL)::FLOAT,0::FLOAT,count(*) FILTER(WHERE first_visit_at IS NULL)::VARCHAR,current_timestamp FROM staging.stg_pendo__account_history"),('completeness_visitor',"SELECT 'Data Completeness Details','visitor_history',count(*)::FLOAT,count(*) FILTER(WHERE visitor_id IS NULL)::FLOAT,0::FLOAT,'0',current_timestamp FROM staging.stg_pendo__visitor_history")]
 for label,new in details:add(id,label,end,end+' UNION ALL '+new,'只补一条缺失详情行；沿契约的UNION按位置映射，不改summary。')
 # Consistency/business sections have all compared numeric columns NULL except violation count in consistency_score.
 checks=[('timestamp_consistency',"SELECT count(*) FROM staging.stg_pendo__event WHERE occurred_at>current_timestamp",'Events with future timestamps'),('account_visitor_relationship',"SELECT count(*) FROM staging.stg_pendo__visitor_history v WHERE v.account_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM staging.stg_pendo__account_history a WHERE a.account_id=v.account_id)",'Visitors without valid account references'),('event_visitor_relationship',"SELECT count(*) FROM staging.stg_pendo__event e WHERE NOT EXISTS(SELECT 1 FROM staging.stg_pendo__visitor_history v WHERE e.visitor_id=v.visitor_id)",'Events with invalid visitor references'),('negative_metrics',"SELECT count(*) FROM staging.stg_pendo__event WHERE num_minutes<0 OR num_events<0",'Events with negative duration or counts'),('chronological_consistency',"SELECT count(*) FROM staging.stg_pendo__account_history WHERE first_visit_at>last_visit_at",'Accounts with first_visit > last_visit')]
 business=[('impossible_session_duration',"SELECT count(*) FROM staging.stg_pendo__event WHERE num_minutes>480",'Sessions longer than 8 hours'),('excessive_daily_events',"SELECT count(*) FROM (SELECT visitor_id,CAST(occurred_at AS DATE) d FROM staging.stg_pendo__event GROUP BY 1,2 HAVING sum(num_events)>10000)",'Excessive daily events'),('duplicate_primary_keys',"SELECT count(*)-count(DISTINCT event_key) FROM staging.stg_pendo__event",'Duplicate event keys'),('inactive_paying_accounts',"SELECT count(*) FROM staging.stg_pendo__account_history a WHERE NOT EXISTS(SELECT 1 FROM staging.stg_pendo__event e WHERE e.account_id=a.account_id AND e.occurred_at>=current_timestamp-INTERVAL 90 DAY)",'Accounts without recent activity')]
 for label,seq,title in [('consistency_details',checks,'Data Consistency Issues'),('business_details',business,'Business Logic Violations')]:
  new=' UNION ALL '.join(f"SELECT '{title}','{name}',({query})::FLOAT,NULL::FLOAT,NULL::FLOAT,'{text}',current_timestamp" for name,query,text in seq)
  add(id,label,end,end+' UNION ALL '+new,'一处恢复整段缺失报告章节；只读原staging，不更改summary。未评分的说明文字只作可读表达。')
 total='((SELECT count(*) FROM staging.stg_pendo__account_history)+(SELECT count(*) FROM staging.stg_pendo__visitor_history)+(SELECT count(*) FROM staging.stg_pendo__event))'
 # Cartesian product: each completeness row repeats 5*4; consistency row repeats 3*4; business row repeats 3*5.
 cons='(1-('+ '+'.join('('+q+')' for _,q,_ in checks)+f')*12.0/nullif({total}*20,0))*100'
 biz='(1-('+ '+'.join('('+q+')' for _,q,_ in business)+f')*15.0/nullif({total}*20,0))*100'
 for col,expr in [('consistency_score',cons),('business_logic_score',biz)]:add(id,col,'NULL::FLOAT '+col,'('+expr+')::FLOAT '+col,'仅恢复一个summary聚合值；笛卡尔积权重按契约3×5×4，不改变其他NULL列。')
 missing="((SELECT count(*) FILTER(WHERE account_id IS NULL)+count(*) FILTER(WHERE first_visit_at IS NULL)+count(*) FILTER(WHERE last_visit_at IS NULL) FROM staging.stg_pendo__account_history)+(SELECT count(*) FILTER(WHERE visitor_id IS NULL) FROM staging.stg_pendo__visitor_history)+(SELECT count(*) FILTER(WHERE visitor_id IS NULL)+count(*) FILTER(WHERE account_id IS NULL)+count(*) FILTER(WHERE occurred_at IS NULL) FROM staging.stg_pendo__event))"
 add(id,'completeness_score','NULL::VARCHAR completeness_score',f'((1-{missing}*1.0/nullif({total}*3,0))*100)::FLOAT::VARCHAR completeness_score','恢复summary完整度公式；该列不在本表官方比较列中，须明确非原因。')
 add(id,'overall_quality_score','NULL::FLOAT overall_quality_score','((try_cast(completeness_score AS FLOAT)+consistency_score+business_logic_score)/3)::FLOAT overall_quality_score','恢复三分数平均，其他列仍保留NULL；遮蔽下允许净改善0。')
 add(id,'quality_grade',"'Poor'::VARCHAR quality_grade","CASE WHEN overall_quality_score>=95 THEN 'Excellent' WHEN overall_quality_score>=85 THEN 'Good' WHEN overall_quality_score>=70 THEN 'Fair' ELSE 'Poor' END quality_grade",'恢复等级分支，输入仍为原NULL；该列不在官方比较列中。')
